CREATE TABLE IF NOT EXISTS qr_issuance(operation_id CHAR(36) PRIMARY KEY,appointment_id VARCHAR(64) NOT NULL UNIQUE,payload_digest VARCHAR(64) NOT NULL,qr_id VARCHAR(64) NOT NULL UNIQUE,phase VARCHAR(24) NOT NULL)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS p4_faults(name VARCHAR(64) PRIMARY KEY,remaining INT NOT NULL DEFAULT 0)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
